mapper.select:
select * from ( SELECT user_id userId, user_no userNo, user_name userName, user_tel_region userTelRegion, user_tel userTel, email, user_gender userGender, DATE_FORMAT( birth_date, '%Y-%m-%d ' ) birthDate, (year(now())-year(birth_date)-1) + ( DATE_FORMAT(birth_date, '%m%d') <= DATE_FORMAT(NOW(), '%m%d') ) as age, height, weight, a.area_id areaId, b.node_full_name userRegion, address, user_city userCity, user_province userProvince, user_country userCountry, user_avatar userAvatar, user_status userStatus, DATE_FORMAT( reg_time, '%Y-%m-%d %H:%i:%s' ) regTime, status, symptom, habits, medical, vip_level vipLevel, user_type userType, device_flag deviceFlag FROM cust_userinfo a LEFT JOIN comm_area b ON a.area_id = b.area_id ) temp where 1=1 and status =1
and userStatus = #{tm}
and ${key} like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%')
order by ${column} ${order}
order by regTime desc

select * from ( SELECT v.voucher_type_id voucherTypeId, v.user_id userId, f.code_name voucherTypeName , CASE v.ref_business WHEN 1 THEN '微信销售' WHEN 2 THEN 'APP销售' WHEN 3 THEN '代理商批发' ELSE '' END refBusinessName, o.order_no orderNo, DATE_FORMAT( v.create_date, '%Y-%m-%d %H:%i:%s' ) createDate, c.company_name companyName, CASE WHEN o.order_id IS NULL THEN '未使用' ELSE '已使用' END `status` FROM cust_user_voucher v LEFT JOIN cust_user_ma_order o ON o.voucher_id = v.voucher_id LEFT JOIN comm_company c ON v.audit_company_id = c.company_id LEFT JOIN v_comm_base_code_detail f ON v.voucher_type_id = f.code_id AND f.type_no = 'CD128' ) temp where 1=1
and userId = #{tm}
and ${key} like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%')
order by ${column} ${order}
order by createDate desc

select * from ( SELECT r.fr_id frId, r.user_id userId, r.fr_user_id frUserId, u.user_name userName, u.user_avatar userAvatar, u.user_tel userTel, u.user_gender userGender, ( YEAR (now()) - YEAR (u.birth_date) - 1 ) + ( DATE_FORMAT(u.birth_date, '%m%d') <= DATE_FORMAT(NOW(), '%m%d') ) userAge, d.code_name relationship, ifnull(r.fr_status, 0) frStatus, ifnull(r.is_emergency_contact, 0) isEmergencyContact FROM cust_user_family_related r LEFT JOIN cust_userinfo u ON r.user_id = u.user_id LEFT JOIN comm_base_code_detail d ON d.code_id = r.type_id AND d.type_no = 'CD601' WHERE ifnull(r.fr_status, 0) = 1 ) temp where 1=1
and frUserId = #{tm}
and ${key} like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%')
order by ${column} ${order}
order by frId desc

SELECT
*
FROM
cust_userinfo a
where status=1


        and user_no=#{userNo} or user_tel=#{userTel}


        and user_no=#{userNo}


        and user_tel=#{userTel}
